9	export function initialToolControl(){return {generation:0,installed:null,events:[],operations:{},enable_id:null};}
10	const UUID=/^[a-f0-9]{8}-[a-f0-9-]{27}$/,HEX=/^[a-f0-9]{64}$/;
11	const ACTIVE=['open','editing','prepared','interrupted','conflicted'];
12	export function createToolUpdates(api){
13	  const {project,safe,json,hash,withLock,gate,fresh,stateLimit,revisions,toolRoot}=api;
14	  const io=revisions.fileTransactions,seen=new Map(),fail=(code,message,extra={})=>{throw userError(message,{code,...extra});};
