16	  const keys=(x,allowed)=>{if(!x||typeof x!=='object'||Array.isArray(x)||Object.keys(x).some(k=>!allowed.includes(k)))fail('TOOL_INPUT_INVALID','工具输入不是对象或含未知字段');};
17	  const keyId=x=>typeof x==='string'&&/^[A-Za-z0-9][A-Za-z0-9_.:-]{0,159}$/.test(x)&&!['__proto__','prototype','constructor'].includes(x);
18	  function control(state){if(state.schema_version<6)return null;const c=state.tool_control;if(!c||!Number.isSafeInteger(c.generation)||c.generation<0||!Array.isArray(c.events)||!c.operations||typeof c.operations!=='object'||Array.isArray(c.operations)||(c.enable_id!==null&&!UUID.test(c.enable_id??''))||(c.installed!==null&&(!HEX.test(c.installed?.runtime_id??'')||!HEX.test(c.installed?.source_content_id??'')||typeof c.installed?.version!=='string')))fail('TOOL_CONTROL_CORRUPT','工具代次状态损坏');return c;}
19	  function observe(p){const c=control(p.state);if(!c)return;const old=seen.get(p.root);if(old&&(!same(old,{project_id:p.state.project_id,generation:c.generation})))fail('TOOL_GENERATION_CHANGED','本进程已读作品的工具代次变化；保留输入并重启新命令');seen.set(p.root,{project_id:p.state.project_id,generation:c.generation});for(const r of c.events){if(!/^\.writer\/objects\/[a-f0-9-]+\.json$/.test(r.ref??'')||digest(p.root,r.ref)!==r.sha256)fail('TOOL_CONTROL_CORRUPT','工具更新事件损坏');}}
