21	  function guard(root,coordination=false){revisions.guardLoaded();if(!coordination||io.transactions(root).some(t=>t.kind==='tool-update'&&!['completed','rolled-back'].includes(t.status)))revisions.assertReady(root);if(path.basename(path.dirname(toolRoot))==='.writer'){const build=identifyBuild(toolRoot);if(!build.ok)fail('TOOL_BUILD_CHANGED','随附包与清单不符；保留现场，从外部入口检查');const own=json(path.resolve(toolRoot,'../state.json'),stateLimit),installed=control(own)?.installed;if(installed&&(installed.runtime_id!==build.runtime_id||installed.source_content_id!==build.observed_content_id))fail('TOOL_BUILD_CHANGED','随附完整内容与已安装代次不符；保留现场，从外部入口检查');}const ref='.writer/state.json';if(exists(root,ref)){const s=json(safe(root,ref),stateLimit);if(s.schema_version>=6){const r=fs.realpathSync(root),old=seen.get(r),current={project_id:s.project_id,generation:control(s).generation};if(old&&!same(old,current))fail('TOOL_GENERATION_CHANGED','工具代次已变更；当前进程不能继续写入');}}}
