28	  function tree(root,ref){const rows={};function visit(r){const f=safe(root,r);if(!fs.existsSync(f))return;const s=fs.lstatSync(f);if(s.isSymbolicLink())fail('TOOL_UNSAFE_PATH','工具目录不接受链接');if(s.isDirectory())for(const n of fs.readdirSync(f).sort())visit(r+'/'+n);else{if(!s.isFile()||s.nlink!==1||s.size>stateLimit)fail('TOOL_UNSAFE_PATH','工具目录包含特殊文件、硬链接或过大文件');rows[r]=hash(fs.readFileSync(f));}}visit(ref);return rows;}
29	  const within=(base,file)=>{const r=path.relative(base,file);return r===''||(!path.isAbsolute(r)&&r!=='..'&&!r.startsWith('..'+path.sep));};
