32	  function options(input){keys(input,['source','documents','legacy_target_acknowledged']);if(typeof input.source!=='string'||!input.source.trim())fail('TOOL_SOURCE_REQUIRED','需显式本地来源source');const docs=input.documents??[];if(!Array.isArray(docs)||new Set(docs).size!==docs.length||docs.some(x=>!WORK_GUIDES.map(n=>'docs/'+n).includes(x)))fail('TOOL_INPUT_INVALID','documents仅可选择受管手册且不得重复');if(input.legacy_target_acknowledged!==undefined&&typeof input.legacy_target_acknowledged!=='boolean')fail('TOOL_INPUT_INVALID','legacy_target_acknowledged须布尔');return {source:input.source,documents:[...docs].sort(),legacy_target_acknowledged:input.legacy_target_acknowledged??false};}
