39	    const blockers=[];try{cleanSessions(p.root);gate(p,'plan');fresh(p);}catch(e){blockers.push({code:e.code??'TOOL_PROJECT_NOT_READY',reason:e.message});}for(const f of Object.keys(oldFiles))if(!allowed.has(f))blockers.push({code:'TOOL_LOCAL_CUSTOMIZATION',file:f,reason:'工具目录有未知文件，默认保留并阻断替换'});
