48	    for(const ref of [...WORK_GUIDES.map(n=>'docs/'+n),'AGENTS.md']){const actual=digest(p.root,ref),next=source.files.find(r=>r.group==='content'&&r.file===ref)?.sha256??null,selected=opts.documents.includes(ref);local.push({file:ref,current_sha256:actual,source_sha256:next,selected,action:selected?'requested':'preserve'});if(!selected||actual===next)continue;
