54	    if(p.state.schema_version!==6)blockers.push({code:'TOOL_PROTOCOL_REQUIRED',schema:p.state.schema_version,reason:'先从新主入口显式启用schema6，更新不暗做迁移'});
55	    const body={project_id:p.state.project_id,revision:p.state.revision,schema_version:p.state.schema_version,generation:control(p.state)?.generation??null,source:{root:source.tool_root,version:source.tool_version,content_id:source.observed_content_id,files:source.files},target:{content_id:target.observed_content_id,version:target.tool_version,files:oldFiles,manifest_sha256:digest(p.root,manifestRef)},documents:opts.documents,legacy_target_acknowledged:opts.legacy_target_acknowledged,local_content:local,document_changes:docChanges,blockers};
