58	  function op(p,input){if(!keyId(input.operation_id)||!Number.isSafeInteger(input.expected_revision))fail('TOOL_INPUT_INVALID','需稳定operation_id与expected_revision');const fingerprint=hash(JSON.stringify(input)),operations=control(p.state)?.operations,old=operations&&Object.hasOwn(operations,input.operation_id)?operations[input.operation_id]:null;if(old){if(old.input_hash!==fingerprint)fail('TOOL_OPERATION_CONFLICT','同operation_id输入不同');return {old:old.result,fingerprint};}if(p.state.revision!==input.expected_revision)fail('REVISION_CHANGED','作品业务revision已变化');return {fingerprint};}
