61	      const p=project(root),operation=op(p,input);if(operation.old)return {...operation.old,unchanged:true};if(p.state.schema_version!==5)fail('TOOL_PROTOCOL_REQUIRED','tool enable仅从schema5显式启用6，先完成原迁移');cleanSessions(p.root);gate(p,'plan');fresh(p);external(p.root);
62	      const proposed=plan(p.root,{source:input.source,legacy_target_acknowledged:input.legacy_target_acknowledged});if(proposed.source.content_id!==input.expected_source_build_id||proposed.target.content_id!==input.expected_target_build_id)fail('TOOL_PLAN_CHANGED','来源或目标指纹变化');if(proposed.blockers.some(x=>x.code!=='TOOL_PROTOCOL_REQUIRED'))fail('TOOL_PLAN_BLOCKED','迁移前先处理更新包/目标阻断',{blockers:proposed.blockers});
63	      const author=proof(p.root,input.author_evidence),id=crypto.randomUUID(),before=read(p.root,'.writer/state.json'),dir=`.writer/tool-enables/${id}`,eventRef=`.writer/objects/${id}.json`;
64	      io.storeBytes(p.root,dir+'/before-state.bin',before,true);freezeProof(p.root,author);
65	      io.metadata(p.root,eventRef,{kind:'tool-enable',before_sha256:hash(before),before_ref:dir+'/before-state.bin',evidence:author.evidence},true);
