72	    const p=project(root),id=input.enable_id,dir=`.writer/tool-enables/${id}`,record=json(safe(p.root,dir+'/enable.json')),before=read(p.root,dir+'/before-state.bin'),current=digest(p.root,'.writer/state.json');
