91	  function protect(root,tx){const current=tree(root,'.writer/tool'),old=tx.protection.tool_files,next=tx.protection.next_tool_files,conflicts=[];for(const file of new Set([...Object.keys(old),...Object.keys(next),...Object.keys(current)])){const actual=current[file]??null;if(actual!==(old[file]??null)&&actual!==(next[file]??null)){const external_ref=actual===null?null:`.writer/transactions/${tx.id}/external/${crypto.randomUUID()}.bin`;if(external_ref)io.storeBytes(root,external_ref,read(root,file),true);conflicts.push({file,before:old[file]??null,after:next[file]??null,external_sha256:actual,external_ref});}}if(conflicts.length){tx.status='conflicted';tx.conflicts=conflicts;io.saveTx(root,tx);fail('TRANSACTION_EXTERNAL_CONFLICT','工具目录存在第三方改动，旧/新/外部均保留',{conflicts});}const skipped=new Set(tx.plan.map(r=>r.file)),filtered=x=>Object.fromEntries(Object.entries(x).filter(([r])=>!skipped.has(r)));if(!same(filtered(io.inventory(root,tx.protection.extra)),filtered(tx.protection.files)))fail('TOOL_BUSINESS_CHANGED','更新期间作品内容变化；保留现场，先核实第三方变更');}
